    throw new TypeError('providers must be functions');
  }

  const location = await resolveBin(label.trim());
  if (!location || typeof location !== 'object' ||
      !Number.isInteger(location.aisle) || location.aisle < 0 ||
      !Number.isInteger(location.bay) || location.bay < 1) {
    throw new TypeError('invalid bin coordinates');
  }

  const result = await readBin(location.bay, location.aisle);
  if (!Array.isArray(result)) throw new TypeError('items must be an array');

  const items = result.map((item) => {
    if (!item || typeof item !== 'object' ||
        typeof item.sku !== 'string' || item.sku.trim() === '' ||
        !Number.isInteger(item.units) || item.units < 0) {
      throw new TypeError('invalid item');
    }
    return { sku: item.sku, units: item.units };
  });

  return { aisle: location.aisle, bay: location.bay, items };
}

module.exports = { lookupBinSnapshot };

