'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['lookupBinSnapshot']);
const { lookupBinSnapshot } = api;

(async () => {
  for (const label of [undefined, null, 4, '', ' \t\n ']) {
    let called = false;
    await assert.rejects(
      lookupBinSnapshot(label, () => { called = true; }, () => { called = true; }),
      TypeError
    );
    assert.equal(called, false);
  }

  for (const pair of [[null, () => []], [() => ({}), null]]) {
    let called = false;
    const resolve = typeof pair[0] === 'function' ? pair[0] : () => { called = true; };
    const read = typeof pair[1] === 'function' ? pair[1] : () => { called = true; };
    await assert.rejects(lookupBinSnapshot('A', pair[0], pair[1]), TypeError);
    assert.equal(called, false);
    void resolve;
    void read;
  }

  const coordinates = { aisle: 0, bay: 1 };
  const suppliedItems = [{ sku: 'SKU-1', units: 0 }, { sku: ' X ', units: 12 }];
  const calls = [];
  const result = await lookupBinSnapshot(
    '  north bin  ',
    async label => { calls.push(['resolve', label]); return coordinates; },
    async (aisle, bay) => { calls.push(['read', aisle, bay]); return suppliedItems; }
  );
  assert.deepEqual(calls, [['resolve', 'north bin'], ['read', 0, 1]]);
  assert.deepEqual(result, { aisle: 0, bay: 1, items: suppliedItems });
  assert.notStrictEqual(result.items, suppliedItems);
  assert.notStrictEqual(result.items[0], suppliedItems[0]);
  suppliedItems[0].sku = 'CHANGED';
  suppliedItems.push({ sku: 'LATE', units: 1 });
  coordinates.aisle = 99;
  assert.deepEqual(result, {
    aisle: 0,
    bay: 1,
    items: [{ sku: 'SKU-1', units: 0 }, { sku: ' X ', units: 12 }]
  });

  assert.deepEqual(
    await lookupBinSnapshot('x', async () => ({ aisle: 8, bay: 2 }), async () => []),
    { aisle: 8, bay: 2, items: [] }
  );

  const badCoordinates = [null, [], {}, { aisle: -1, bay: 1 }, { aisle: 1.2, bay: 1 },
    { aisle: 0, bay: 0 }, { aisle: 0, bay: 1.5 }];
  for (const value of badCoordinates) {
    let reads = 0;
    await assert.rejects(
      lookupBinSnapshot('x', async () => value, async () => { reads += 1; return []; }),
      TypeError
    );
    assert.equal(reads, 0);
  }

  const badItems = [null, {}, [null], [{ sku: '', units: 1 }],
    [{ sku: 4, units: 1 }], [{ sku: 'A', units: -1 }], [{ sku: 'A', units: 1.5 }]];
  for (const value of badItems) {
    await assert.rejects(
      lookupBinSnapshot('x', async () => ({ aisle: 1, bay: 1 }), async () => value),
      TypeError
    );
  }

  const resolveError = new Error('resolve failed');
  await assert.rejects(
    lookupBinSnapshot('x', async () => { throw resolveError; }, async () => []),
    error => error === resolveError
  );
  const readError = new Error('read failed');
  await assert.rejects(
    lookupBinSnapshot('x', async () => ({ aisle: 1, bay: 2 }), async () => { throw readError; }),
    error => error === readError
  );
})().catch(error => { console.error(error); process.exitCode = 1; });

